import os
import sys

def solve():
    if os.path.exists("revegetate.in"):
        data = list(map(int, open("revegetate.in").read().split()))
    else:
        data = list(map(int, sys.stdin.read().split()))
    n, m = data[0], data[1]
    adj = [[] for _ in range(n + 1)]
    idx = 2
    for _ in range(m):
        u, v = data[idx], data[idx + 1]
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    color = [0] * (n + 1)
    for i in range(1, n + 1):
        used = {color[nbr] for nbr in adj[i] if color[nbr] != 0}
        for c in range(1, 5):
            if c not in used:
                color[i] = c
                break

    ans = "".join(str(color[i]) for i in range(1, n + 1))
    if os.path.exists("revegetate.in"):
        with open("revegetate.out", "w") as f:
            f.write(ans + "\n")
    else:
        print(ans)

if __name__ == "__main__":
    solve()

