#include <cstdio>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    if (FILE* f = fopen("revegetate.in", "r")) {
        fclose(f);
        freopen("revegetate.in", "r", stdin);
        freopen("revegetate.out", "w", stdout);
    }
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> color(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        bool used[5] = {};
        for (int nbr : adj[i]) {
            if (color[nbr] != 0) used[color[nbr]] = true;
        }
        for (int c = 1; c <= 4; c++) {
            if (!used[c]) {
                color[i] = c;
                break;
            }
        }
        cout << color[i];
    }
    cout << '\n';
    return 0;
}

